// Writes internal/connectors/singlebyte_tables.go: what Node's TextDecoder
// (ICU) makes of each byte in every single-byte WHATWG encoding. ICU keeps
// C1 controls and a few bytes that golang.org/x/text turns into U+FFFD.
//
// Run from apps/app: npx tsx ../server/testdata/gen/singlebyte-tables.ts
import fs from "node:fs"
import path from "node:path"

const names = [
  "ibm866", "iso-8859-2", "iso-8859-3", "iso-8859-4", "iso-8859-5", "iso-8859-6", "iso-8859-7", "iso-8859-8",
  "iso-8859-8-i", "iso-8859-10", "iso-8859-13", "iso-8859-14", "iso-8859-15", "iso-8859-16", "koi8-r", "koi8-u",
  "macintosh", "windows-874", "windows-1250", "windows-1251", "windows-1252", "windows-1253", "windows-1254",
  "windows-1255", "windows-1256", "windows-1257", "windows-1258", "x-mac-cyrillic",
]

const bytes = Buffer.from(Array.from({ length: 256 }, (_, i) => i))
let src = `// Code generated by testdata/gen/singlebyte-tables.ts from Node's TextDecoder; DO NOT EDIT.

package connectors

// singleByte maps a WHATWG encoding name to the code point Node's
// TextDecoder gives each byte.
var singleByte = map[string]*[256]rune{
`
for (const name of names) {
  const text = new TextDecoder(name).decode(bytes)
  const cps = Array.from(text, (c) => c.codePointAt(0)!)
  if (cps.length !== 256) throw new Error(`${name}: ${cps.length} code points`)
  src += `\t${JSON.stringify(name)}: {\n`
  for (let i = 0; i < 256; i += 16) src += `\t\t${cps.slice(i, i + 16).map((c) => `0x${c.toString(16).padStart(4, "0")}`).join(", ")},\n`
  src += "\t},\n"
}
src += "}\n"

const file = path.resolve(import.meta.dirname, "../../internal/connectors/singlebyte_tables.go")
fs.writeFileSync(file, src)
console.log(`wrote ${file}: ${names.length} encodings`)
